-- relationships kept in columns of app.feedback: audited when they change; the feed hears of every row
CREATE FUNCTION authz_int."feedback__col_audit_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('feedback', ARRAY(SELECT n."id"::text FROM new_rows n), 'insert');
  RETURN NULL;
END $f$;

-- @object trigger "authz_feedback_col_audit_ins" ON "app"."feedback"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."feedback"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_feedback_col_audit_ins" AFTER INSERT ON "app"."feedback" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."feedback__col_audit_ins"()';
  ELSE
    RAISE NOTICE '"app"."feedback" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

CREATE FUNCTION authz_int."feedback__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('feedback', ARRAY(SELECT n."id"::text FROM new_rows n UNION SELECT o."id"::text FROM old_rows o), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'feedback', n."id"::text, 'project', n."project_id"::text, jsonb_build_object('column', 'project_id', 'was', o."project_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."project_id" IS DISTINCT FROM o."project_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'feedback'
          AND a.object_id = n."id"::text AND a.relation = 'project' AND a.detail->>'column' = 'project_id'
          AND a.subject_id IS NOT DISTINCT FROM n."project_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."project_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'feedback', n."id"::text, 'author', n."author_id"::text, jsonb_build_object('column', 'author_id', 'was', o."author_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."author_id" IS DISTINCT FROM o."author_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'feedback'
          AND a.object_id = n."id"::text AND a.relation = 'author' AND a.detail->>'column' = 'author_id'
          AND a.subject_id IS NOT DISTINCT FROM n."author_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."author_id"));
    END IF;
  RETURN NULL;
END $f$;

-- @object trigger "authz_feedback_col_audit_upd" ON "app"."feedback"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."feedback"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_feedback_col_audit_upd" AFTER UPDATE ON "app"."feedback" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."feedback__col_audit_upd"()';
  ELSE
    RAISE NOTICE '"app"."feedback" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

