-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."feedback__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."project_id" IS DISTINCT FROM OLD."project_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'feedback', NEW."id"::text, 'project', NEW."project_id"::text, jsonb_build_object('column', 'project_id', 'was', OLD."project_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."author_id" IS DISTINCT FROM OLD."author_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'feedback', NEW."id"::text, 'author', NEW."author_id"::text, jsonb_build_object('column', 'author_id', 'was', OLD."author_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;

-- @object trigger "authz_feedback_col_audit_row" ON "app"."feedback"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."feedback"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_feedback_col_audit_row" AFTER UPDATE ON "app"."feedback" FOR EACH ROW WHEN (OLD."project_id" IS DISTINCT FROM NEW."project_id" OR OLD."author_id" IS DISTINCT FROM NEW."author_id") EXECUTE FUNCTION authz_int."feedback__col_audit_row"()';
  ELSE
    RAISE NOTICE '"app"."feedback" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

-- feedback.project.owner
CREATE VIEW authz_int."feedback__project__owner" AS
  SELECT r."id" AS id FROM "app"."feedback" r WHERE r."project_id" IN (SELECT id FROM authz_int."project__owner");

CREATE VIEW authz_gen."feedback__project__owner" WITH (security_barrier) AS SELECT id FROM authz_int."feedback__project__owner";

-- feedback.read (line 38): project.owner
CREATE VIEW authz_int."feedback__read" AS
  SELECT id FROM authz_int."feedback__project__owner";

CREATE VIEW authz_gen."feedback__read" WITH (security_barrier) AS SELECT id FROM authz_int."feedback__read";

ALTER TABLE "app"."feedback" ENABLE ROW LEVEL SECURITY;
-- its partitions and the tables that inherit from it: row-level security on, with no policies of their own,
-- so they are read and written through it only (read directly, they would skip its rules and triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = '"app"."feedback"'::regclass
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

CREATE FUNCTION authz_gen."app.feedback:insert:items"(p_row "app"."feedback") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce("feedback"."author_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = "feedback"."project_id")), false),
    coalesce((SELECT authz_int.scope_cmd('app.feedback', 'insert')), false),
    coalesce(true, false),
    coalesce(EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = "feedback"."project_id"), false),
    coalesce(coalesce("feedback"."author_id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "feedback";
END;

CREATE FUNCTION authz_gen."app.feedback:insert:why"(p_row "app"."feedback") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.feedback:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : project.view and author  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.feedback insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on app.feedback'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'project.view';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("feedback"."project_id")::text AS id FROM (SELECT (p_row).*) AS "feedback") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('project', v_t.id, 'view') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'author';
END $f$;

CREATE FUNCTION authz_gen."app.feedback:insert:refuse"(p_row "app"."feedback") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.feedback:insert:why"(p_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'insert this row into app.feedback',
    DETAIL = v_lines, SCHEMA = 'app', TABLE = 'feedback', CONSTRAINT = 'authz_insert',
    HINT = 'rowstile help AZ709';
END $f$;

CREATE FUNCTION authz_gen."app.feedback:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."feedback"; r_new "app"."feedback";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.feedback:insert:why"(jsonb_populate_record(NULL::"app"."feedback", coalesce(p_row, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.feedback', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."feedback" x WHERE x."id" = p_id::integer;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.feedback: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for app.feedback: nobody may update its rows'];
END $f$;

-- app.feedback select (line 54): read
CREATE POLICY "authz_select" ON "app"."feedback" FOR SELECT TO conf_app
  USING (((SELECT authz_int.scope_cmd('app.feedback', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = "feedback"."project_id")));
COMMENT ON POLICY "authz_select" ON "app"."feedback" IS 'rowstile';

-- app.feedback insert (line 55): project.view and author
CREATE POLICY "authz_insert" ON "app"."feedback" FOR INSERT TO conf_app
  WITH CHECK (((SELECT authz_int.scope_cmd('app.feedback', 'insert')) AND (coalesce("feedback"."author_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = "feedback"."project_id")))
    OR authz_gen."app.feedback:insert:refuse"(ROW("feedback".*)::"app"."feedback"));
COMMENT ON POLICY "authz_insert" ON "app"."feedback" IS 'rowstile';

-- Foreign keys that delete governed rows skip row-level security
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child, con.confrelid::regclass AS parent
           FROM pg_constraint con
           WHERE con.contype = 'f' AND con.confdeltype = 'c' AND con.conrelid IN ('"app"."projects"'::regclass, '"app"."notes"'::regclass, '"app"."inbox"'::regclass, '"app"."feedback"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is ON DELETE CASCADE: deleting a row of % also deletes rows of %, and cascades skip row-level security, so a user could remove rows they cannot see. Use ON DELETE RESTRICT unless that is intended.',
      c.conname, c.child, c.parent, c.child;
  END LOOP;
END $fk$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_integer integer;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'service' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__viewer" v WHERE v.id = o."id"))));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = v_integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = v_integer AND ((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = v_integer AND (EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "app"."inbox" o WHERE o."id" = v_integer AND (coalesce(o."recipient_id" = (SELECT authz.uid()), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'feedback' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "app"."feedback" o WHERE o."id" = v_integer AND (EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'project.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'project.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__viewer" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__viewer" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE o."id" > p_after::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__viewer" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'project.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE o."id" > p_after::integer AND coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::integer AND (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::integer AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'message.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE coalesce(o."recipient_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE coalesce(o."recipient_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE o."id" > p_after::integer AND coalesce(o."recipient_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'feedback.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."feedback" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."feedback" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."feedback" o
        WHERE o."id" > p_after::integer AND EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'user' THEN names := ARRAY[]::text[];
    WHEN 'service' THEN names := ARRAY[]::text[];
    WHEN 'project' THEN names := ARRAY['edit', 'view', 'share']::text[];
    WHEN 'note' THEN names := ARRAY['edit', 'view']::text[];
    WHEN 'message' THEN names := ARRAY['read']::text[];
    WHEN 'feedback' THEN names := ARRAY['read']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

-- Why a write is or would be refused, as the signed-in user: an insert (p_row: the new row as JSON), or an
-- update or delete of the row whose id is p_id (for an update, p_row: the new values). NULL when that row isn't
-- there or the user can't see it (404, not 403). SELECT authz.explain_rule('app.files', 'update', '11')
CREATE OR REPLACE FUNCTION authz.explain_rule(p_table text, p_command text, p_id text DEFAULT NULL, p_row jsonb DEFAULT NULL)
RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_command IS NULL OR p_command NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION 'explain_rule explains insert, update or delete, not %', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_table
    WHEN 'app.projects' THEN RETURN authz_gen."app.projects:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.notes' THEN RETURN authz_gen."app.notes:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.inbox' THEN RETURN authz_gen."app.inbox:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.feedback' THEN RETURN authz_gen."app.feedback:rules:explain"(p_command, p_id, p_row);
    ELSE RAISE EXCEPTION 'the policy has no rules for table %', p_table USING ERRCODE = 'undefined_table', HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

CREATE FUNCTION authz_int."feedback__author__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."author_id" FROM "app"."feedback" r WHERE r."id" = p_id AND r."author_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."feedback__read__who"(p_id integer) RETURNS SETOF integer
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM (SELECT r."project_id" AS id FROM "app"."feedback" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg, LATERAL authz_int."project__owner__who"(tg.id) x
$f$;

CREATE FUNCTION authz_int."feedback__project__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN

  RETURN NEXT pad || 'no   you do not hold feedback.project';
END $f$;

CREATE FUNCTION authz_int."feedback__author__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."feedback" r WHERE r."author_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'author: author_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold feedback.author';
END $f$;

CREATE FUNCTION authz_int."feedback__read__why"(p_id integer, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."feedback__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'feedback.read = project.owner';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."feedback__project__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'project.owner';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."project_id" AS id FROM "app"."feedback" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('project', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'project is a project you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'project is project '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has owner' ELSE ', without owner' END;
      IF NOT ('project:owner:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."project__owner__why"(v_t.id::integer, p_depth + 1 + 1, p_seen || ('project:owner:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."users" "users" WHERE "users"."id" = p_id::integer
        AND true);
    WHEN 'service' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."services" "services" WHERE "services"."id" = p_id::integer
        AND true);
    WHEN 'project' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."projects" "projects" WHERE "projects"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.projects', 'select')) AND (coalesce("projects"."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = "projects"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = "projects"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__viewer" v WHERE v.id = "projects"."id")));
    WHEN 'note' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."notes" "notes" WHERE "notes"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.notes', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = "notes"."project_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."inbox" "inbox" WHERE "inbox"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.inbox', 'select')) AND coalesce("inbox"."recipient_id" = (SELECT authz.uid()), false));
    WHEN 'feedback' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."feedback" "feedback" WHERE "feedback"."id" = p_id::integer
        AND (SELECT authz_int.scope_cmd('app.feedback', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = "feedback"."project_id"));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked with authz.can, as that user.
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_integer integer;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  BEGIN
    PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
    PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
    CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'service' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."project__edit__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."project__view__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."project__share__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."note__edit__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."note__view__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."message__read__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'feedback' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."feedback__read__who"(v_integer) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM set_config('authz.scopes', v_scopes, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_integer integer;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  -- another user's access: only for people who may inspect the object (the signed-in user may explain their own;
  -- a service whose id is a user's may not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS DISTINCT FROM authz.uid()::text
     AND NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  BEGIN
    IF p_user IS NOT NULL THEN
      PERFORM set_config('authz.user_id', p_user, true);
      PERFORM set_config('authz.principal_type', '', true);
      PERFORM authz_int.sign();
    END IF;
    v_ok := authz.can(p_type, p_id, p_perm);
    RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
      || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
    CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'service' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."project__edit__why"(v_integer, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."project__view__why"(v_integer, 1, '{}');
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."project__share__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."note__edit__why"(v_integer, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."note__view__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."message__read__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'feedback' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."feedback__read__why"(v_integer, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM authz_int.sign();
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('conf_app');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'conf_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'conf_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'conf_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'conf_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'conf_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'conf_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'conf_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'conf_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relforcerowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"']::text[]) x) LOOP
    IF r.relowner = v_role OR pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      IF NOT r.relforcerowsecurity THEN
        severity := 'error'; object := r.tbl::text;
        problem := format('is owned by %s (or a role it belongs to): owners skip row-level security unless you ALTER TABLE %s FORCE ROW LEVEL SECURITY', 'conf_app', r.tbl);
        RETURN NEXT;
      END IF;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'conf_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'conf_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile', 'rowfence', 'authzc')
             AND p.polname NOT IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'conf_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'conf_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules and the triggers of the table above
  -- (apply turns row-level security on for the ones there are then; later ones are found here)
  FOR r IN WITH RECURSIVE d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i
             JOIN (SELECT to_regclass(t) AS tbl, true AS governed FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) t
                   UNION ALL SELECT to_regclass(t), false FROM unnest(ARRAY['"app"."members"', '"app"."project_services"']::text[]) t) x
               ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'conf_app', r.tbl, r.part, 'conf_app');
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE')
                                 OR (r.governed AND has_table_privilege(v_role, r.part, 'SELECT'))) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'conf_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- tables that inherit (not partitions), made since the last apply: Postgres runs a table's row triggers for
  -- its own rows only, and applying gives them to each table under it (whatever the app role may do there:
  -- written through the table above, their rows need no privilege of their own)
  FOR r IN SELECT c.child, string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c GROUP BY c.child LOOP
    severity := 'error'; object := r.child::text;
    problem := format('inherits from a table the policy has rules or a type for, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, so a rule on a column is not checked on the rows stored here, and their shares stay when their key changes (missing here: %s). Apply the policy again (it makes them)', r.names);
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a column it may insert or update, not GENERATED ALWAYS): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'conf_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'conf_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"app"."members"', 'project.member', false), ('"app"."project_services"', 'project.service', false)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'conf_app', r.tbl, 'conf_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'conf_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'conf_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES ('"app"."notes"', 'project_id', 'note.project', 'relation note.project project_id', 'nobody'), ('"app"."notes"', 'author_id', 'note.author', 'relation note.author author_id', 'nobody')) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- JIT for the app role: checks are many small subplans, which JIT may spend longer compiling than running
  IF coalesce((SELECT split_part(c, '=', 2) FROM pg_db_role_setting s, unnest(s.setconfig) c
               WHERE s.setrole = v_role AND c LIKE 'jit=%'
                 AND s.setdatabase IN (0, (SELECT d.oid FROM pg_database d WHERE d.datname = current_database()))
               ORDER BY s.setdatabase DESC LIMIT 1), current_setting('jit')) IN ('on', 'true', '1') THEN
    severity := 'performance'; object := 'conf_app';
    problem := format('runs with JIT on: permission checks are many small subplans, and JIT can take longer to compile a read than to run it (a third of a second for a large one): ALTER ROLE %s SET jit = off', 'conf_app');
    RETURN NEXT;
  END IF;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."feedback"', 'insert'), ('"app"."feedback"', 'select'), ('"app"."inbox"', 'insert'), ('"app"."inbox"', 'select'), ('"app"."notes"', 'delete'), ('"app"."notes"', 'insert'), ('"app"."notes"', 'select'), ('"app"."notes"', 'update'), ('"app"."projects"', 'select')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'conf_app', upper(r.cmd), upper(r.cmd), r.tbl, 'conf_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES ('project', 'service', 'relation project.service')) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  severity := 'info'; object := 'service';
  problem := 'signs in, but has no manage_keys permission, so nobody can make API keys for it: add can manage_keys = ... (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'type service'), '?') || ')';
  RETURN NEXT;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"', '"app"."services"', '"app"."users"', '"app"."members"', '"app"."project_services"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view', 'rowfence masked view', 'authzc masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'conf_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.feedback', 'app.inbox', 'app.notes', 'app.projects', 'app.services', 'app.users', 'app.members', 'app.project_services']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."projects"', 'owner_id', 'project.owner: find objects by owner_id'), ('"app"."members"', 'project_id', 'project.member: find the members of an object'), ('"app"."members"', 'user_id', 'project.member: find what a subject is in'), ('"app"."project_services"', 'project_id', 'project.service: find the members of an object'), ('"app"."project_services"', 'service_id', 'project.service: find what a subject is in'), ('"app"."notes"', 'project_id', 'note.project: find objects by project_id'), ('"app"."notes"', 'author_id', 'note.author: find objects by author_id'), ('"app"."inbox"', 'recipient_id', 'message.recipient: find objects by recipient_id'), ('"app"."feedback"', 'project_id', 'feedback.project: find objects by project_id'), ('"app"."feedback"', 'author_id', 'feedback.author: find objects by author_id')) v(tbl, col, why) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them
    IF NOT EXISTS (SELECT 1 FROM pg_index i
                   WHERE i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:cardinality(string_to_array(r.col, ', ')) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(r.col, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- What is wrong with this connection, for the app to check when it starts: SELECT * FROM authz.connection_check()
-- 'error': the rules don't apply to the role this connection runs as; 'performance'; 'info'. No rows: all is well.
CREATE OR REPLACE FUNCTION authz.connection_check() RETURNS TABLE (severity text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me oid := to_regrole(authz_int.caller_role()); v_app oid := to_regrole('conf_app'); r record;
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s is a superuser: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT; RETURN;
  END IF;
  IF (SELECT rolbypassrls FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s has BYPASSRLS: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- a table's owner (or a role with its rights) skips row-level security, unless the table forces it
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             AND NOT c.relforcerowsecurity AND pg_has_role(v_me, c.relowner, 'USAGE') LOOP
    severity := 'error';
    problem := format('%s owns %s (or has its owner''s rights): owners skip row-level security', v_me::regrole, r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a table with rules whose row-level security is off: the rules don't apply
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."feedback"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x) AND NOT c.relrowsecurity LOOP
    severity := 'error';
    problem := format('row-level security is off on %s: the policy''s rules don''t apply to it', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a login that switched to the app role (SET ROLE) but is an administrator: RESET ROLE leaves row-level
  -- security, and its sessions are believed without a signature
  FOR r IN SELECT l.oid::regrole AS login FROM pg_roles l, pg_namespace n
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER')) LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, a superuser, BYPASSRLS or the policy''s owner, and switched to %s: RESET ROLE leaves row-level security, and who is signed in is believed without a signature. Log in as the app role', r.login, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  IF v_app IS NULL OR NOT pg_has_role(v_me, v_app, 'USAGE') THEN
    severity := 'error';
    problem := format('%s is not the policy''s app role %s, nor a member of it: the rules apply to %s only',
                      v_me::regrole, 'conf_app', 'conf_app');
    RETURN NEXT;
  END IF;
  IF current_setting('jit') = 'on' THEN
    severity := 'performance';
    problem := 'JIT is on: reads through row-level security can spend more time compiling than running (ALTER ROLE ... SET jit = off)';
    RETURN NEXT;
  END IF;
END $f$;

